def cookie_parser(cookie_string: str) -> dict[str, str]:
    """
    Parse a cookie string into a dictionary of key-value pairs.

    This function handles cookies in a lenient way, similar to how browsers parse them.
    """
    cookie_dict: dict[str, str] = {}

    # Try using the standard library's cookie parser first
    try:
        cookie: http_cookies.SimpleCookie = http_cookies.SimpleCookie()
        cookie.load(cookie_string)
        for key, morsel in cookie.items():
            cookie_dict[key] = morsel.value
    except http_cookies.CookieError:
        pass

    # Fall back to manual parsing for cookies that the standard library rejects
    for chunk in cookie_string.split(";"):
        chunk = chunk.strip()
        if not chunk:
            continue

        if "=" in chunk:
            key, _, val = chunk.partition("=")
            key = key.strip()
            val = val.strip()

            # Strip quotes if present
            if val and val[0] == '"' and val[-1] == '"':
                val = val[1:-1]

            if key and key not in cookie_dict:
                cookie_dict[key] = val
        else:
            # Cookie with no value
            key = chunk.strip()
            if key and key not in cookie_dict:
                cookie_dict[key] = ""

    return cookie_dict
